using Microsoft.EntityFrameworkCore;

// Cosmos DB project — demonstrates EF Core 9 breaking changes and fixes.

class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        options.UseCosmos(
            "https://localhost:8081",
            "C2y6yDjf5/R+ob0N8A7Cgv30VRDJIWEHLM+4QDU5DE2nQ9nDuVTqobD4b8mGGyPMbIZnqyMsEcaGQy67XIw/Jw==",
            "SampleDb");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");
            entity.HasPartitionKey(p => p.Category);

            // EF Core 9 breaking change #1: Cosmos DB discriminator property renamed
            // from "Discriminator" to "$type". Existing documents use "Discriminator",
            // so we must explicitly configure the old property name to avoid data loss.
            entity.HasDiscriminator<string>("Discriminator");
        });
    }

    // EF Core 9 breaking change #2: Synchronous I/O on Cosmos DB is no longer supported.
    // All queries and SaveChanges calls MUST use async equivalents.
    //
    // BEFORE (throws InvalidOperationException in EF Core 9):
    //   var items = db.Products.ToList();
    //   db.SaveChanges();
    //
    // AFTER (correct):
    //   var items = await db.Products.ToListAsync();
    //   await db.SaveChangesAsync();

    public async Task<List<Product>> GetProductsAsync()
    {
        return await Products.ToListAsync();
    }

    public async Task AddProductAsync(Product product)
    {
        Products.Add(product);
        await SaveChangesAsync();
    }
}

class Product
{
    public string Id { get; set; } = Guid.NewGuid().ToString();
    public string Name { get; set; } = "";
    public string Category { get; set; } = "";
}

